import {
  Mjml,
  MjmlBody,
  MjmlFont,
  MjmlHead,
  MjmlImage,
  MjmlPreview,
  MjmlWrapper,
  MjmlColumn,
  MjmlSection,
  MjmlText,
} from "@faire/mjml-react";
import type { ReactNode } from "react";

import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

export const HeaderEmailShell = ({
  children,
  pageBackgroundColor,
  preview,
  theme,
}: {
  children: ReactNode;
  pageBackgroundColor: string;
  preview: string;
  theme: EmailTheme;
}) => (
  <Mjml>
    <MjmlHead>
      <MjmlPreview>{preview}</MjmlPreview>
      <MjmlFont href="https://rsms.me/inter/inter.css" name="Inter" />
    </MjmlHead>
    <MjmlBody
      backgroundColor={pageBackgroundColor}
      width={theme.containerWidth}
    >
      <MjmlWrapper padding="0">{children}</MjmlWrapper>
    </MjmlBody>
  </Mjml>
);

export const HeaderLogo = ({
  align = "left",
  alt,
  href,
  src,
}: {
  align?: "center" | "left" | "right";
  alt: string;
  href: string;
  src: string;
}) => (
  <MjmlImage
    align={align}
    alt={alt}
    href={href}
    padding="0"
    src={src}
    width="55px"
  />
);

export type HeaderWithUserDetailsAlignment = "left" | "right";

export type HeaderWithUserDetailsAvatar = "initials" | "image";

export interface HeaderWithUserDetailsProps {
  theme?: EmailTheme;
  logoSrc?: string;
  logoAlt?: string;
  logoHref?: string;
  userName?: string;
  userEmail?: string;
  initials?: string;
  avatarSrc?: string;
  avatarAlt?: string;
  avatar?: HeaderWithUserDetailsAvatar;
  alignment?: HeaderWithUserDetailsAlignment;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  avatarBackgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  mutedTextColor?: string;
}

const fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

export const HeaderWithUserDetailsSection = (
  props: Omit<HeaderWithUserDetailsProps, "theme">
) => {
  const {
    alignment,
    avatar,
    avatarAlt,
    avatarBackgroundColor,
    avatarSrc,
    backgroundColor,
    headingColor,
    initials,
    logoAlt,
    logoHref,
    logoSrc,
    mutedTextColor,
    userEmail,
    userName,
  } = {
    alignment: "left" as HeaderWithUserDetailsAlignment,
    avatar: "initials" as HeaderWithUserDetailsAvatar,
    avatarAlt: "",
    avatarBackgroundColor: "#f3f4f6",
    backgroundColor: "#fffffe",
    headingColor: "#030712",
    initials: "JD",
    logoAlt: "Maizzle",
    logoHref: "https://example.com",
    logoSrc: emailAsset("maizzle-insignia.png"),
    mutedTextColor: "#6b7280",
    ...props,
  };
  const imageOnRight = avatar === "image" && alignment === "right";
  const resolvedName =
    userName ?? (imageOnRight ? "Joanne Smith" : "John Adams");
  let defaultEmail = "johnadams@gmail.com";
  if (avatar === "image") {
    defaultEmail = imageOnRight ? "joanne@example.com" : "ajohn@example.com";
  }
  const resolvedEmail = userEmail ?? defaultEmail;
  const resolvedAvatar =
    avatarSrc ??
    (imageOnRight
      ? emailAsset("reviews/avatar.jpg")
      : emailAsset("reviews/avatar-2.jpg"));
  const logo = (
    <MjmlColumn padding="0" verticalAlign="middle" width="15%">
      <HeaderLogo
        align={alignment}
        alt={logoAlt}
        href={logoHref}
        src={logoSrc}
      />
    </MjmlColumn>
  );
  const avatarColumn = (
    <MjmlColumn padding="0 8px" verticalAlign="middle" width="12%">
      {avatar === "image" ? (
        <MjmlImage
          align="center"
          alt={avatarAlt}
          borderRadius="9999px"
          padding="0"
          src={resolvedAvatar}
          width="32px"
        />
      ) : (
        <MjmlText
          align="center"
          backgroundColor={avatarBackgroundColor}
          color={headingColor}
          fontFamily={fontFamily}
          fontSize="10px"
          fontWeight="600"
          lineHeight="32px"
          padding="0"
        >
          {initials}
        </MjmlText>
      )}
    </MjmlColumn>
  );
  const details = (
    <MjmlColumn padding="0" verticalAlign="middle" width="73%">
      <MjmlText
        align={alignment === "left" ? "right" : "left"}
        color={headingColor}
        fontFamily={fontFamily}
        fontSize="14px"
        fontWeight="600"
        lineHeight="20px"
        padding="0"
      >
        {resolvedName}
      </MjmlText>
      <MjmlText
        align={alignment === "left" ? "right" : "left"}
        color={mutedTextColor}
        fontFamily={fontFamily}
        fontSize="12px"
        lineHeight="16px"
        padding="0"
      >
        {resolvedEmail}
      </MjmlText>
    </MjmlColumn>
  );
  return (
    <MjmlSection backgroundColor={backgroundColor} padding="24px">
      {alignment === "left" ? logo : avatarColumn}
      {details}
      {alignment === "left" ? avatarColumn : logo}
    </MjmlSection>
  );
};

export const HeaderWithUserDetails = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: HeaderWithUserDetailsProps) => (
  <HeaderEmailShell
    pageBackgroundColor={pageBackgroundColor}
    preview="User account"
    theme={theme}
  >
    <HeaderWithUserDetailsSection {...props} />
  </HeaderEmailShell>
);

HeaderWithUserDetails.PreviewProps = {
  alignment: "left",
  avatar: "initials",
  theme: defaultTheme,
} satisfies HeaderWithUserDetailsProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
